VALUES ('hintek-driftrond-vattenkraft', 'Daglig tillsyn – vattenkraftstation', '', 'Generell mall baserad på offentliga källor: driftstatus, nivåer och flöden, turbin, generator och lager, damm och intag, miljövillkor och säkerhet – med trender och gränsvärden per anläggning.', 'Levereras av HINTEK (inbyggd kontrolltyp).', 'cyan', 'gauge', 'SERVICE', true, true, 'forms', 'PUBLISHED', '{"schema":2,"blocks":[{"id":"vk-a9","type":"section","title":"Rondinformation","description":"","newPage":false,"blocks":[{"id":"vk-n1","type":"note","title":"Generell mall baserad på offentliga källor","text":"Mallen bygger på RIDAS, dammsäkerhetsförordningen, Svenska kraftnäts vägledningar, Miljösamverkan Sveriges egenkontroll för vattenkraft, USBR FIST och UNIDO (docs/kallor/vattenkraft.md). Den innehåller inga gränsvärden: sätt anläggningens egna nivåer under Gränsvärden – från vattendomen, tillverkarens anvisningar och drift- och tillsynsprogrammet – och ta bort eller lägg till punkter så att mallen stämmer med anläggningens program. Gör en rond per aggregat när stationen har flera.","visibility":{"task":true,"pdf":true},"width":"full","style":"card","showIf":{"key":"","op":"eq","value":""}},{"id":"vk-f2","type":"field","key":"tid","label":"Datum och tid för ronden","input":"datetime","required":true,"help":"","unit":"","min":null,"max":null,"options":[],"multiple":false,"allowNotApplicable":true,"deviationOn":"NONE","deviationOptions":[],"defaultValue":null,"allowedMin":null,"allowedMax":null,"decimals":null,"maxLength":null,"width":"third","visibility":{"task":true,"pdf":true},"prefill":"none","highlight":false,"momentSwitch":false,"placeholder":"","pdfLabel":"","showIf":{"key":"","op":"eq","value":""},"remarks":false,"limitKey":"","trend":false},{"id":"vk-f3","type":"field","key":"station","label":"Station / anläggning","input":"text","required":true,"help":"","unit":"","min":null,"max":null,"options":[],"multiple":false,"allowNotApplicable":true,"deviationOn":"NONE","deviation